// Generates lib/src/generated/pindoro_tokens.dart from tokens/tokens.json.
// Run from anywhere: `dart run packages/pindoro_design/tool/generate_tokens.dart`.
import 'dart:convert';
import 'dart:io';

void main() {
  final packageDir = File.fromUri(Platform.script).parent.parent;
  final tokensFile = File('${packageDir.path}/tokens/tokens.json');
  final outFile = File(
    '${packageDir.path}/lib/src/generated/pindoro_tokens.dart',
  );

  final tokens =
      jsonDecode(tokensFile.readAsStringSync()) as Map<String, Object?>;
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/generate_tokens.dart from tokens/tokens.json.',
    )
    ..writeln('// DO NOT EDIT. Edit tokens.json and run `just gen`.')
    ..writeln()
    ..writeln("import 'package:flutter/widgets.dart';")
    ..writeln()
    ..writeln('abstract final class PindoroTokens {');

  for (final MapEntry(:key, :value) in tokens.entries) {
    if (key.startsWith(r'$')) continue;
    final name = _camelCase(key);
    switch (value) {
      case String hex when key.startsWith('color.'):
        out.writeln('  static const Color $name = Color(${_argb(hex, key)});');
      case {'duration_ms': final int ms, 'curve': final String curve}
          when key.startsWith('motion.'):
        out
          ..writeln(
            '  static const Duration $name = Duration(milliseconds: $ms);',
          )
          ..writeln('  static const Curve ${name}Curve = Curves.$curve;');
      case num n:
        out.writeln('  static const double $name = $n;');
      default:
        throw FormatException('Unsupported token "$key": $value');
    }
  }
  out.writeln('}');

  outFile
    ..createSync(recursive: true)
    ..writeAsStringSync(out.toString());
  final format = Process.runSync(Platform.resolvedExecutable, [
    'format',
    outFile.path,
  ]);
  if (format.exitCode != 0) {
    throw ProcessException('dart', ['format'], '${format.stderr}');
  }
  stdout.writeln('Wrote ${outFile.path}');
}

String _camelCase(String key) {
  final parts = key.split(RegExp('[._]'));
  return parts.first +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}

String _argb(String hex, String key) {
  final digits = hex.replaceFirst('#', '').toUpperCase();
  return switch (digits.length) {
    6 => '0xFF$digits',
    8 => '0x$digits',
    _ => throw FormatException('Bad colour for "$key": $hex'),
  };
}
